// Menu illustrations and explicit status feedback share the existing art direction.
const POLISH_ART={basket:'data:image/webp;base64,',craft:'data:image/webp;base64,',boss:'data:image/webp;base64,'};
function illustratedEmpty(image,title,body){return '<div class="empty illustrated-empty"><img src="'+POLISH_ART[image]+'" alt=""><strong>'+clean(title)+'</strong><p>'+clean(body)+'</p></div>'}
const STATUS_BUFFS=[['flow',1,'Xuất thần'],['pull',2,'Lực kéo +30%'],['eye',3,'Mắt đại bàng'],['luck',4,'May mắn +15%'],['guard',5,'Dây bất tử'],['radar',6,'Radar'],['titan',7,'Tiết kiệm thể lực'],['speed',8,'Cuộn cước ×2'],['gold',9,'Giá cá ×2'],['shield',10,'Chặn 1 bất lợi'],['xp',4,'EXP ×2'],['bite',8,'Cắn mồi nhanh'],['clear',6,'Tránh rác'],['crit',3,'Chí mạng']];
const TONICS=[['pull',3,30],['eye',2,30],['luck',3,30],['guard',3,10],['radar',2,30],['titan',3,30],['speed',4,20],['gold',4,30],['shield',3,30]];
let statusStamp='';
function statusBadge(group,id,name,seconds){return '<span class="status-chip '+group+'">'+packIcon(artKey(group,id,'icon'))+'<span>'+clean(name)+(seconds>0?' <b>'+Math.ceil(seconds)+'s</b>':'')+'</span></span>'}
function updateStatuses(){
 let html='';for(const [key,id,name] of STATUS_BUFFS)if(buffs[key]>0)html+=statusBadge('buff',id,name,buffs[key]);
 if(stun>0)html+=statusBadge('buff',5,'Cá đóng băng',stun);
 if(guard>0)html+=statusBadge('buff',10,'Bảo vệ',guard);
 if(powerBuff>0)html+=statusBadge('buff',2,'Chiêu tăng lực',powerBuff);
 if(speedBuff>0)html+=statusBadge('buff',8,'Chiêu tăng tốc',speedBuff);
 if(S.boostUntil>Date.now())html+=statusBadge('buff',8,'Tăng tốc',(S.boostUntil-Date.now())/1000);
 if(S.stamina<5)html+=statusBadge('debuff',1,'Kiệt sức',0);
 if(state==='fight'){
  if(weatherIndex===5)html+=statusBadge('debuff',2,'Gió giật',weatherLeft);
  if(/rỉ/.test(debuff))html+=statusBadge('debuff',3,'Dây rỉ sét',weatherLeft);
  if(shock>0)html+=statusBadge('debuff',4,'Tê tay',shock);
  if(weatherIndex===4)html+=statusBadge('debuff',5,'Tê băng',weatherLeft);
  if(weatherIndex===3)html+=statusBadge('debuff',6,'Mù sương',weatherLeft);
  if(weatherIndex===10)html+=statusBadge('debuff',7,'Nhả để kéo',weatherLeft);
  if(target?.boss&&/Mập/.test(target.n))html+=statusBadge('debuff',8,'Cá mập va thuyền',0);
  if(weatherIndex===8)html+=statusBadge('debuff',9,'Nước nóng',weatherLeft);
  if(entangled>0)html+=statusBadge('debuff',10,'Rong quấn',entangled);
 }
 if(html!==statusStamp){statusStamp=html;$('buffs').innerHTML=html;}
 $('buffs').hidden=!!menu||!html;
 $('action').classList.toggle('exhausted',S.stamina<5);
 $('action').classList.toggle('shocked',shock>0&&state==='fight');
}
const polishUpdateUI=updateUI;
updateUI=function(){polishUpdateUI();updateStatuses();write('weather',WEATHER[weatherIndex].ic+' '+WEATHER[weatherIndex].n+' · '+Math.ceil(weatherLeft)+'s');};
function statusGuide(){let h='<div class="summary">Giật hoàn hảo để nhận Xuất thần. Chế tạo bùa ở Xưởng để kích hoạt buff. Biểu tượng trên màn chơi ghi thời gian còn lại; thời tiết đổi mỗi 30 giây.</div>';for(const [key,id,name] of STATUS_BUFFS.slice(0,10))h+=tile(packIcon(artKey('buff',id,'icon')),name,({flow:'Giật hoàn hảo: lực kéo +20% trong 10s.',pull:'Lực kéo +30%.',eye:'Hiện bóng cá và cân nặng khi đang chờ.',luck:'Tăng 15% độ may mắn khi chọn cá.',guard:'Ngăn đứt dây khi đang có hiệu lực.',radar:'Hiện tên và độ hiếm cá đang cắn.',titan:'Giảm một nửa thể lực tiêu hao.',speed:'Tốc độ kéo ×2.',gold:'Giá trị cá vào túi ×2.',shield:'Chặn một lần sét, rong quấn hoặc ăn mòn.'})[key]);for(const d of CATALOG.debuff)h+=tile(catalogIcon('debuff',d.id),d.n,d.fx);return h;}
const polishRenderMenu=renderMenu;
renderMenu=function(){
 polishRenderMenu();
 if(menuSub==='status')$('panel').innerHTML=statusGuide();
 if(menuSub==='bag'&&!S.inv.length)$('panel').querySelector('.empty').outerHTML=illustratedEmpty('basket','Túi cá đang trống','Thả câu, giật khi cá cắn rồi giữ để kéo. Cá bắt được nằm ở đây; bán cá để nâng cấp.');
 if(menuSub==='craft'){
  $('panel').insertAdjacentHTML('afterbegin',illustratedEmpty('craft','Xưởng đồ câu','Thu gom nguyên liệu, chế mồi và chuẩn bị bùa hỗ trợ.'));
  let h='<div class="summary">Bùa hỗ trợ · dùng ngay, không cộng dồn thời gian</div>';
  for(const [key,cost,duration] of TONICS){const b=STATUS_BUFFS.find(b=>b[0]===key);h+=tile(packIcon(artKey('buff',b[1],'icon')),b[2],duration+' giây · '+cost+' nguyên liệu',button('Dùng bùa','tonic:'+key,S.materials<cost));}
  $('panel').insertAdjacentHTML('beforeend',h);
 }
 if(menuSub==='boss')$('panel').insertAdjacentHTML('afterbegin','<div class="menu-banner"><img src="'+POLISH_ART.boss+'" alt=""><p><b>Săn bóng lớn</b><br>Cần cấp 3 · 1 mồi Tim Rồng. Chọn boss tại vùng đang câu; mồi được tự chọn khi bắt đầu.</p></div>');
 if(menuSub==='aquarium'&&!S.tank.length)$('panel').insertAdjacentHTML('afterbegin','<div class="summary">Hồ chưa có cá. Vào Túi cá → Thả hồ để bắt đầu nuôi và nhận thu nhập.</div>');
 if(!$('panel').innerHTML.trim())$('panel').innerHTML='<div class="empty">Chọn một mục ở thanh phía trên để xem đồ câu và hoạt động.</div>';
 $('sheet').classList.toggle('upgrade-sheet',menuSub==='up');
 $('panel').scrollTop=0;updateStatuses();
};
const polishPanelClick=$('panel').onclick;
$('panel').onclick=function(e){const b=e.target.closest('[data-do]');if(b?.dataset.do.startsWith('tonic:')){if(b.disabled)return;const key=b.dataset.do.split(':')[1],r=TONICS.find(x=>x[0]===key);if(r&&S.materials>=r[1]){S.materials-=r[1];buffs[key]=r[2];toast('Bùa đã kích hoạt · '+r[2]+'s');save();renderMenu();}return;}polishPanelClick(e);};
LABEL.status='Trạng thái';tabGroups.more.splice(5,0,'status');
